# %% [markdown]
# ## 5. Exercise 3 — `counterfactual_pairs`: change one feature, keep the content
#
# To find out whether the model uses length, change the length and leave everything else alone. In a pair
# ordered by the gold reward (`gold_pairs` gives the better answer's features and the worse answer's), there are two clean ways:
#
# * **swap** the feature: the better answer gets the worse answer's value and vice versa. If the model had been leaning
#   on the feature, and the feature differs systematically between better and worse answers, the lean now points the wrong way and
#   accuracy falls. A feature that is unrelated to quality gives the model nothing to lose when it is swapped.
# * **equalise** the feature: both answers get the **mean of the two** values. The feature can no longer separate them.
#
# `better` and `worse` are arrays of shape `(n, d)`, row *i* of each belonging to pair *i*. Return the two changed arrays
# as a **tuple** `(new_better, new_worse)` of new **float** arrays; every other column and the arrays you were given stay untouched.
# `mode` must be exactly `"swap"` or `"equalise"`: any other string, capitals and spelling variants included, raises `ValueError`.
#
# <details><summary>💡 Hint 1 — what to think about</summary>
#
# What happens to the original arrays if you assign into a slice of a view of them? What dtype does a mean of two integers need?
#
# </details>
# <details><summary>💡 Hint 2 — the approach in words</summary>
#
# Copy both arrays as floats first. For a swap, exchange the one column's values between the two copies (take care that the second
# assignment does not read what the first already overwrote). For an equalise, both copies get the mean of the pair's two values in that
# column. A mode other than exactly "swap" or "equalise" (capital letters do not count), a `column` below 0 or not below the number of
# columns, or two arrays that are not two-dimensional and of the same shape, raise `ValueError`.
#
# </details>

# %%
def counterfactual_pairs(better, worse, column, mode):
    """Change one feature of every pair, by swapping it or equalising it.

    Args:
        better, worse: feature arrays of shape (n, d); row i of each is one pair.
        column: the feature to change, with 0 <= column < d.
        mode: exactly ``"swap"`` (the two answers exchange that feature's values) or ``"equalise"`` (both take the mean of the two).

    Returns:
        A tuple ``(new_better, new_worse)`` of new float arrays of shape (n, d). The inputs are not changed and the new arrays
        share no memory with them. A `mode` that is neither of the two (``"Swap"`` is not ``"swap"``), a `column` outside 0..d-1, or arrays that are not
        two-dimensional with the same shape raise ``ValueError``, in either mode.

    Example:
        >>> nb, nw = counterfactual_pairs(np.array([[1, 2]]), np.array([[4, 8]]), 1, "swap")
        >>> nb.tolist(), nw.tolist()
        ([[1.0, 8.0]], [[4.0, 2.0]])
    """
    # YOUR CODE HERE
    raise NotImplementedError


def _check_counterfactual_pairs() -> None:
    better = np.array([[1, 2, 3], [4, 5, 6]])
    worse = np.array([[7, 8, 9], [1, 2, 3]])
    kept_better, kept_worse = better.copy(), worse.copy()
    result = counterfactual_pairs(better, worse, 1, "swap")
    assert type(result) is tuple and len(result) == 2, f"return a tuple (new_better, new_worse); got a {type(result).__name__}"
    nb, nw = result
    assert nb.tolist() == [[1, 8, 3], [4, 2, 6]] and nw.tolist() == [[7, 2, 9], [1, 5, 3]], (
        f"swap of column 1 should give {[[1, 8, 3], [4, 2, 6]]} and {[[7, 2, 9], [1, 5, 3]]}; got {nb.tolist()} and {nw.tolist()}. "
        "Only that column changes, and the two answers exchange values: both must end up with the OTHER one's original value.")
    nb, nw = counterfactual_pairs(better, worse, 2, "swap")
    assert nb.tolist() == [[1, 2, 9], [4, 5, 3]] and nw.tolist() == [[7, 8, 3], [1, 2, 6]], "the last column is a valid column: swap it"
    nb, nw = counterfactual_pairs(better, worse, 0, "equalise")
    assert nb.tolist() == [[4, 2, 3], [2.5, 5, 6]] and nw.tolist() == [[4, 8, 9], [2.5, 2, 3]], (
        f"equalise of column 0 should give {[[4, 2, 3], [2.5, 5, 6]]} and {[[4, 8, 9], [2.5, 2, 3]]}; got {nb.tolist()} and {nw.tolist()}. "
        "Both answers take the mean of the pair's two values, which for integers needs floats (the second pair's mean is 2.5).")
    nb, nw = counterfactual_pairs(np.array([[0.5, 1.0]]), np.array([[0.25, 3.0]]), 1, "equalise")
    assert nb.tolist() == [[0.5, 2.0]] and nw.tolist() == [[0.25, 2.0]], "float input, equalise column 1: both answers take 2.0, the mean of 1.0 and 3.0"
    rng = np.random.default_rng(8)
    many_better, many_worse = rng.normal(size=(30, 5)), rng.normal(size=(30, 5))
    for column in range(5):
        for mode in ("swap", "equalise"):
            nb, nw = counterfactual_pairs(many_better, many_worse, column, mode)
            want_b, want_w = many_better.copy(), many_worse.copy()
            for i in range(30):
                x, y = many_better[i, column], many_worse[i, column]
                want_b[i, column], want_w[i, column] = (y, x) if mode == "swap" else ((x + y) / 2.0, (x + y) / 2.0)
            assert np.allclose(nb, want_b, rtol=0, atol=1e-12) and np.allclose(nw, want_w, rtol=0, atol=1e-12), (
                f"column {column}, {mode}: only that column changes, row by row; a swap exchanges the two values, an equalise gives both the pair's mean")
    for dtype in (int, float):
        ints_better = np.array([[1, 2, 3], [4, 5, 6], [0, 1, 2]], dtype=dtype)
        ints_worse = np.array([[7, 8, 9], [1, 2, 3], [3, 3, 3]], dtype=dtype)
        kept_b, kept_w = ints_better.copy(), ints_worse.copy()
        for column, mode in ((0, "swap"), (1, "equalise"), (2, "swap"), (2, "equalise")):
            nb, nw = counterfactual_pairs(ints_better, ints_worse, column, mode)
            faults = []
            if not ((ints_better == kept_b).all() and (ints_worse == kept_w).all()):
                faults.append("the arrays you were given were changed; copy them first (np.asarray does not copy a float array, np.array does)")
            if nb.dtype != float or nw.dtype != float:
                faults.append(f"return float arrays; got {nb.dtype} and {nw.dtype}")
            if np.shares_memory(nb, ints_better) or np.shares_memory(nw, ints_worse) or np.shares_memory(nb, nw):
                faults.append("the returned arrays must be new arrays, not views of the inputs or of each other")
            assert not faults, f"{np.dtype(dtype).name} input, column {column}, {mode}: " + "; ".join(faults)
    assert (better == kept_better).all() and (worse == kept_worse).all(), "the arrays you were given were changed; copy them first"
    bad_calls = [(better, worse, 1, "swop"), (better, worse, 1, "equalize"), (better, worse, 1, "Swap"), (better, worse, 1, "EQUALISE"), (better, worse, 1, " swap")]
    for mode in ("swap", "equalise"):
        bad_calls += [(better, worse, 3, mode), (better, worse, -1, mode), (better, worse[:1], 1, mode), (better[0], worse[0], 0, mode),
                      (np.zeros((2, 2, 2)), np.ones((2, 2, 2)), 1, mode)]
    for bad in bad_calls:
        assert _raises_value_error(counterfactual_pairs, *bad), (
            f"counterfactual_pairs{bad[2:]} must raise ValueError: a mode that is not exactly 'swap' or 'equalise' (no capitals, no spaces), "
            "a column outside 0..d-1 (negative included) or arrays that are not two-dimensional with one shape, in either mode")
    print("exercise 3 looks right")


_try("exercise 3", _check_counterfactual_pairs)

